#!/usr/bin/env bash\n# Build the Flutter app for release with optimisations.\nset -euo pipefail\n\n# Clean previous builds\nflutter clean\n\n# Create release build with obfuscation and split debug info\nflutter build apk --release \\n  --obfuscate \\n  --split-debug-info=debug_info/\n\n# Optional: Build for iOS as well\n# flutter build ios --release \\n#   --obfuscate \\n#   --split-debug-info=ios_debug_info/\n\n# Build for web if needed\n# flutter build web --release\n\n# Print success message\nprintf '\\n\u2714\\uFE0F Release build completed.\\n'\n